package com.universe.community.service; import com.universe.community.dto.response.PostLikeResponse; import com.universe.community.entity.*; import com.universe.community.repository.*; import com.universe.global.exception.*; import com.universe.global.security.CurrentUser; import com.universe.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class PostLikeService {private final PostLikeRepository likes;private final CommunityPostRepository posts;private final UserRepository users; @Transactional public PostLikeResponse like(Long postId){var p=posts.findByIdAndStatus(postId,PostStatus.ACTIVE).orElseThrow(()->new BusinessException(ErrorCode.POST_NOT_FOUND));var u=users.findById(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHORIZED));if(u.getSchool()==null||!u.getSchool().getId().equals(p.getSchool().getId()))throw new BusinessException(ErrorCode.CROSS_SCHOOL_ACCESS);if(likes.existsByPostIdAndUserId(postId,u.getId()))throw new BusinessException(ErrorCode.LIKE_ALREADY_EXISTS);likes.save(PostLike.builder().post(p).user(u).build());return new PostLikeResponse(postId,true,likes.countByPostId(postId));} @Transactional public PostLikeResponse unlike(Long postId){var u=users.findById(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHORIZED));var like=likes.findByPostIdAndUserId(postId,u.getId()).orElseThrow(()->new BusinessException(ErrorCode.LIKE_NOT_FOUND));likes.delete(like);return new PostLikeResponse(postId,false,likes.countByPostId(postId));}}
